        .logo {
            text-align: center;
            margin-bottom: 30px;
        }
        .login-form {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }
        input {
            padding: 10px;
            border: 1px solid #ddd;
            border-radius: 4px;
            font-size: 16px;
        }
        button {
            background: #007bff;
            color: white;
            padding: 10px 20px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 16px;
        }
        button:hover {
            background: #0056b3;
        }
        .info {
            margin-top: 20px;
            font-size: 14px;
            color: #666;
        }
        .progress {
            width: 100%;
            height: 10px;
            background: #eee;
            border-radius: 5px;
            overflow: hidden;
        }
        .progress-bar {
            height: 100%;
            background: #4CAF50;
            transition: width 0.3s ease;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="logo">
            <h1>Secure Bank</h1>
            <p>Log in securely</p>
        </div>
        <form class="login-form" id="loginForm">
            <input type="text" placeholder="Username" required>
            <input type="password" placeholder="Password" required>
            <div class="info">
                <label>Security Code: 1234</label>
                <input type="text" placeholder="Enter Security Code" required>
            </div>
            <button type="submit">Sign In</button>
        </form>
        <div class="progress">
            <div class="progress-bar" id="progressBar" style="width: 0%"></div>
        </div>
        <div id="message"></div>
    </div>

    <script>
        document.getElementById('loginForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const progressBar = document.getElementById('progressBar');
            const messageDiv = document.getElementById('message');

            messageDiv.textContent = "Processing login...";
            progressBar.style.width = "100%";

            setTimeout(() => {
                window.location.href = '/thank_you';
            }, 1500);
        });
    </script>
</body>
</html>
```

