        # Email content
        subject = "Your Account Has Been Compromised!"
        body = """Your account has been compromised. Click here to verify: http://localhost:5000/phishing"""
        to = ["test@example.com"]
        message = f"From: Support Team <support@company.com>\nTo: {to}\nSubject: {subject}\n\n{body}"
        server.sendmail(to, message)
