@app.route('/')
def home():
    return render_template('login.html')

@app.route('/submit', methods=['POST'])
def submit():
    data = {
        'username': request.form.get('username'),
        'password': request.form.get('password'),
        'name': 'Test User',
        'account_number': '1234567890',
        'security_question': 'What is your favorite color?',
        'security_answer': 'Blue',
    }
    with open('simulation_data.txt', 'a') as f:
        f.write(f"Simulation: {data}\n")
    return "Thank you for your response!"

if __name__ == '__main__':
    # Send the email
    with app.app_context():
        subject = "Security Verification Required"
        sender = "Support Team <support@example.com>"
        recipients = ["testuser@example.com"]
        template_vars = {
            'username': 'Test User',
            'name': 'Test User',
            'link': f"{request.url_root}submit"
        }
        mail.send_mail(
            subject=subject,
            body=email_template,
            sender=sender,
            to=recipients,
            cc=None,
            bcc=None,
            reply_to=None,
            body_template=template_vars
        )

    # Start the server
    app.run(host='0.0.0.0', port=5000)
```

### Ethical Considerations:
- **Local Testing**: Ensure the simulation runs on a local network to avoid external access.
- **Disclaimers**: Inform users in the email and simulation that this is a test.
- **Data Handling**: Use temporary storage for captured data and ensure it's deleted after the simulation.

This setup provides a controlled environment to study user responses without causing harm.<｜end▁of▁sentence｜>

