               background-color: #007bff;
               color: white;
               padding: 10px 20px;
               border: none;
               border-radius: 4px;
               cursor: pointer;
               width: 100%;
           }
           button:hover {
               background-color: #0056b3;
           }
           .message {
               color: #ff4444;
               margin-top: 10px;
               text-align: center;
           }
         </style>
       </head>
