    <html>
        <head>
            <title>Login - Secure Account Verification</title>
            <style>
                body {
                    font-family: Arial, sans-serif;
                    background: #f0f2f5;
                    margin: 0;
                    padding: 0;
                }
                .login-container {
                    background: white;
                    padding: 2rem;
                    border-radius: 5px;
                    box-shadow: 0 0 10px rgba(0,0,0,0.1);
