- Ensure users are aware they're partaking in a simulation and that their data is not at risk.

### Example Code:

```python
from flask import Flask, render_template, request, redirect, url_for, flash
from flask_mail import Mail, Message

app = Flask(__name__)
mail = Mail(app)

@app.route('/')
def login_page():
    return render_template('login.html')

@app.route('/login', methods=['POST'])
def handle_login():
    email = request.form.get('email')
    password = request.form.get('password')

    # For demonstration, no actual storage
    if email == "example@domain.com" and password == "password":
        flash("Thank you for verifying your account! You can now log in.")
        return redirect(url_for('login'))
    else:
        flash("Invalid email or password. Please try again.")
        return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=True)
