```python
# Import necessary libraries
from flask import Flask, render_template
from flask_mail import Mail, Message
import smtplib
import os

# Initialize the app and mail service
app = Flask(__name__)
mail = Mail(app)

# Create a fake email and password
fake_email = "user@example.com"
fake_password = "password123"

# Create a simple login page
login_page = """
<!DOCTYPE html>
<html>
<head>
    <title>Login - Secure System</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            background: #f0f0f0;
        }
        .login-container {
            max-width: 400px;
            margin: 100px auto;
            padding: 20px;
            border: 1px solid #ccc;
            border-radius: 5px;
        }
