            color: #333;
            text-align: center;
        }
        .form-group {
            margin: 10px 0;
        }
        input {
            width: 100%;
            padding: 8px;
            margin-top: 5px;
        }
        button {
            background-color: #4CAF50;
            color: white;
            padding: 10px 20px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        button:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>
    <div class="login-container">
        <h1>Secure Login</h1>
        <form action="/success" method="post">
            <div class="form-group">
                <label for="username">Username</label>
                <input type="text" id="username" name="username" required>
            </div>
            <div class="form-group">
                <label for="password">Password</label>
                <input type="password" id="password" name="password" required>
            </div>
            <button type="submit">Login</button>
        </form>
        <p>Forgot Password? <a href="#">Click here</a></p>
    </div>
</body>
</html>
"""

# Create an email template
email_template = """
Hello {user},

We noticed unusual activity on your account. To verify your identity, please click the link below.

https://{domain}/login

If you didn't request this email, ignore it and check your spam folder.
"""

# Create a server route for handling login form
@app.route('/', methods=['GET', 'POST'])
def login():
    if request.method == 'GET':
        return render_template('login.html')
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if username == fake_email and password == fake_password:
            return "Success! You have successfully logged in."
        else:
            return "Invalid credentials. Please try again."

# Create a route for the success page
@app.route('/success')
def success():
    return "Login successful!"

# Run the server
if __name__ == '__main__':
    # Configure email settings
    app.config['MAIL_SERVER'] = 'localhost'
    app.config['MAIL_PORT'] = 1025
    mail.send_message('Phishing Test Email',
                     recipient=fake_email,
                     body=email_template.format(user="Test User"),
                     sender="Support Team <support@example.com>")

    app.run(debug=True, port=8000)
```

