                         'Verification Required',
                         sender='Support Team <support@example.com>',
                         body=f'Your account verification request has been received. Please click the link below to verify: http://localhost:8000/verify/'
                     )
                     msg.send(to='user@example.com')

             return render_template('success.html')
         return redirect('login')

