    MAIL_USERNAME='your_email@example.com',
    MAIL_PASSWORD='your_password'
)

mail = Mail(app)

@app.route('/')
def login_page():
    return render_template('login.html')

@app.route('/submit', methods=['POST'])
def handle_submission():
